def test_agg_explode(self):
    t = hl.Table.parallelize([hl.struct(a=[1, 2]), hl.struct(a=hl.empty_array(hl.tint32)), hl.struct(a=hl.missing(hl.tarray(hl.tint32))), hl.struct(a=[3]), hl.struct(a=[hl.missing(hl.tint32)])])
    self.assertCountEqual(t.aggregate(hl.agg.explode(lambda elt: hl.agg.collect(elt), t.a)), [1, 2, None, 3])

def test_nulls_in_distinct_joins_1(self):
    mr = hl.utils.range_matrix_table(7, 3, 4)
    matrix1 = mr.key_rows_by(new_key=hl.if_else((mr.row_idx == 3) | (mr.row_idx == 5), hl.missing(hl.tint32), mr.row_idx))
    matrix2 = mr.key_rows_by(new_key=hl.if_else((mr.row_idx == 4) | (mr.row_idx == 6), hl.missing(hl.tint32), mr.row_idx))
    joined = matrix1.select_rows(idx1=matrix1.row_idx, idx2=matrix2.rows()[matrix1.new_key].row_idx)

    def row(new_key, idx1, idx2):
        return hl.Struct(new_key=new_key, idx1=idx1, idx2=idx2)
    expected = [row(0, 0, 0), row(1, 1, 1), row(2, 2, 2), row(4, 4, None), row(6, 6, None), row(None, 3, None), row(None, 5, None)]
    self.assertEqual(joined.rows().collect(), expected)

def test_agg_cols_filter(self):
    t = hl.utils.range_matrix_table(1, 10)
    tests = [(agg.filter(t.col_idx > 7, agg.collect(t.col_idx + 1).append(0)), [9, 10, 0]), (agg.filter(t.col_idx > 7, agg.explode(lambda elt: agg.collect(elt + 1).append(0), [t.col_idx, t.col_idx + 1])), [9, 10, 10, 11, 0]), (agg.filter(t.col_idx > 7, agg.group_by(t.col_idx % 3, hl.array(agg.collect_as_set(t.col_idx + 1)).append(0))), {0: [10, 0], 2: [9, 0]})]
    for aggregation, expected in tests:
        self.assertEqual(t.select_rows(result=aggregation).result.collect()[0], expected)

def test_agg_cols_explode(self):
    t = hl.utils.range_matrix_table(1, 10)
    tests = [(agg.explode(lambda elt: agg.collect(elt + 1).append(0), hl.if_else(t.col_idx > 7, [t.col_idx, t.col_idx + 1], hl.empty_array(hl.tint32))), [9, 10, 10, 11, 0]), (agg.explode(lambda elt: agg.explode(lambda elt2: agg.collect(elt2 + 1).append(0), [elt, elt + 1]), hl.if_else(t.col_idx > 7, [t.col_idx, t.col_idx + 1], hl.empty_array(hl.tint32))), [9, 10, 10, 11, 10, 11, 11, 12, 0]), (agg.explode(lambda elt: agg.filter(elt > 8, agg.collect(elt + 1).append(0)), hl.if_else(t.col_idx > 7, [t.col_idx, t.col_idx + 1], hl.empty_array(hl.tint32))), [10, 10, 11, 0]), (agg.explode(lambda elt: agg.group_by(elt % 3, agg.collect(elt + 1).append(0)), hl.if_else(t.col_idx > 7, [t.col_idx, t.col_idx + 1], hl.empty_array(hl.tint32))), {0: [10, 10, 0], 1: [11, 0], 2: [9, 0]})]
    for aggregation, expected in tests:
        self.assertEqual(t.select_rows(result=aggregation).result.collect()[0], expected)

def test_agg_cols_group_by(self):
    t = hl.utils.range_matrix_table(1, 10)
    tests = [(agg.group_by(t.col_idx % 2, hl.array(agg.collect_as_set(t.col_idx + 1)).append(0)), {0: [1, 3, 5, 7, 9, 0], 1: [2, 4, 6, 8, 10, 0]}), (agg.group_by(t.col_idx % 3, agg.filter(t.col_idx > 7, hl.array(agg.collect_as_set(t.col_idx + 1)).append(0))), {0: [10, 0], 1: [0], 2: [9, 0]}), (agg.group_by(t.col_idx % 3, agg.explode(lambda elt: agg.collect(elt + 1).append(0), hl.if_else(t.col_idx > 7, [t.col_idx, t.col_idx + 1], hl.empty_array(hl.tint32)))), {0: [10, 11, 0], 1: [0], 2: [9, 10, 0]})]
    for aggregation, expected in tests:
        self.assertEqual(t.select_rows(result=aggregation).result.collect()[0], expected)

